export const BODY: string = "\n<p>كل تصميم جيد يبدأ بلوحة ألوان، وكل لوحة جيدة تبدأ في مكان حقيقي: صورة أو صورة علامة أو مشهد يبدو جيدًا أصلًا.</p>\n<p>مستخرج لوحة ألوان يجد الألوان المهيمنة لتلك الصورة نيابة عنك: يمسح البكسلات ويجمعها في الألوان التي تهم ويسلمك لوحة مرتبة في ثوانٍ.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصور</a> من CompressMyPic، وماذا تفعل كل ميزة، وكيف تحوّل صورة إلى لوحة تستطيع استخدامها فعلًا.</p>\n<h2 id=\"what-is-a-palette-extractor\">ما مستخرج لوحة الألوان؟</h2>\n<p>مستخرج لوحة ألوان يحلل صورة ويعيد أهم ألوانها كمجموعة عينات: كل عينة تُظهر اللون وقيمه HEX وRGB وHSL، ونصيب الصورة الذي يغطيه.</p>\n<p>ترفع صورة وتختار كم لونًا تريد، وتبني الأداة اللوحة: والنتيجة مخطط ألوان جاهز يعمل معًا أصلًا، لأن الألوان خرجت من نفس الصورة. وتقبل الأداة صيغ صور شائعة حتى 20 MB، ما يغطي صور هواتف وصور منتج ولقطات شاشة وصور علامات: وتُعالج كلها محليًا في متصفحك.</p>\n<p>يستخدمه المصممون لبدء مشروع، ويستخدمه المطورون لتنسيق موقع من صورة رئيسية، ويستخدمه صناع المحتوى للحفاظ على اتساق ألوانهم عبر منشوراتهم.</p>\n<h2 id=\"median-cut-quantization\">كيف يعمل تكميم القطع الوسيطي</h2>\n<p>يبني المستخرج لوحتك بخوارزمية تسمى تكميم القطع الوسيطي: تقنية قياسية لتقليص آلاف الألوان إلى مجموعة صغيرة تمثيلية.</p>\n<p>تبدأ الخوارزمية بكل بكسلات الصورة في صندوق واحد: تجد قناة اللون ذات النطاق الأوسع، وتقسم الصندوق إلى اثنين عند الوسيط، وتكرر القسمة حتى تحصل على صناديق بقدر الألوان التي طلبتها. ويساهم كل صندوق بعدها بلون: متوسط البكسلات داخله. والنتيجة مجموعة ألوان تمثل الصورة كلها بعدل، مع حصول المناطق الكبيرة على حصتها العادلة.</p>\n<p>القطع الوسيطي سريع ومتوقع، لهذا يُستخدم في أدوات في كل مكان: لا يحتاج خادمًا ولا نموذج تعلم آلي، ويعمل فورًا في متصفحك.</p>\n<h2 id=\"how-many-colors\">كم لونًا: من 3 إلى 12 عينة</h2>\n<p>منزلق يتحكم في كم عينة تحتوي اللوحة، من 3 إلى 12، والقيمة الافتراضية 6: الكمية تغيّر طابع اللوحة لا طولها فقط.</p>\n<p>ثلاثة ألوان تعطيك مخططًا أدنى: مهيمن وثانوي ولمسة: ذلك يكفي لموقع نظيف أو ملصق بسيط أو معالجة شعار. وستة ألوان هي القيمة المتوازنة الافتراضية: تلتقط النغمات الرئيسية لمعظم الصور دون تقسيم نغمات متشابهة إلى شبه مكررات يصعب تمييزها.</p>\n<p>واثنا عشر لونًا هي الحد الأقصى، وتنفع لصور معقدة بمناطق مختلفة كثيرة: والمقايضة أن النغمات المتشابهة تبدأ في الظهور مرتين، فلوحة 12 لونًا غالبًا تحتوي تكرارًا تستطيع إزالته.</p>\n<h2 id=\"percentage-badges\">شارة النسبة المئوية في كل عينة</h2>\n<p>كل عينة تحمل شارة نسبة مئوية تُظهر كم من الصورة يغطي ذلك اللون: لون بنسبة 42 بالمئة يهيمن على الصورة، بينما لون بنسبة 3 بالمئة لمسة صغيرة.</p>\n<p>النسب تخبرك تسلسل اللوحة الهرمي: أكبر لون غالبًا الخلفية أو الشخص الرئيسي، والأصغر هي التفاصيل التي تمنح الصورة طابعها. واستخدم النسب عند بناء تصميم: قاعدة شائعة أن تعطي اللون المهيمن أكبر مساحة، واللون الثانوي دور دعم، والألوان الأصغر فقط للمسات والتفاصيل.</p>\n<p>وإذا كانت عينتان بنفس النسبة تقريبًا ونفس اللون تقريبًا، فهما غالبًا لون قسّمته الخوارزمية: احتفظ بواحدة وتخلص من الأخرى، وتصبح اللوحة أنظف.</p>\n<h2 id=\"proportional-color-strip\">شريط الألوان النسبي</h2>\n<p>تحت العينات، تعرض الأداة شريط ألوان نسبيًا: شريط واحد مقسم إلى مقاطع حسب نصيب كل لون من الصورة: إنه اللوحة كصورة.</p>\n<p>الشريط يجعل التوازن مرئيًا في لمحة: صورة بمقطع ضخم وشظايا عدة هي صورة بلون مهيمن قوي ولمسات صغيرة، بينما شريط متساوٍ يعني ألوانًا متوازنة. ويستخدم المصممون الشريط للحكم إن كانت لوحة ستعمل: لوحة شريطها معظمه لون واحد ستنتج تصاميم هادئة، بينما لوحة بمقاطع كثيرة متساوية ستنتج تصاميم حيوية.</p>\n<p>ويساعدك الشريط أيضًا على اكتشاف اللمسة: أصغر مقطع غالبًا اللون الذي يجعل الصورة لا تُنسى، وهو غالبًا الخيار الصحيح للأزرار والتفاصيل المميزة.</p>\n<h2 id=\"copy-css-custom-properties\">نسخ CSS: خصائص مخصصة بنقرة واحدة</h2>\n<p>زر \"نسخ CSS\" ينسخ كل العينات كخصائص مخصصة لـCSS في إجراء واحد: تحصل على متغيرات مثل --color-1 حتى --color-6، كل منها بقيمة HEX، جاهزة للصق في ورقة أنماط.</p>\n<p>هذا أسرع وأأمن من نسخ الأكواد واحدًا واحدًا: التصدير يحافظ على كل لون بترتيبه، دون أخطاء نسخ أو عينات مفقودة. وغيّر عدد العينات ويتحدث التصدير: تستطيع الانتقال من 6 ألوان إلى 4 دون إعادة رفع الصورة، وCSS المنسوخ يعكس المجموعة الجديدة فورًا.</p>\n<p>ولبكسل واحد دقيق بدل لوحة كاملة، استخدم <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a>: المنتقي يقرأ بكسلًا تختاره، بينما المستخرج يرتب ألوان الصورة كلها.</p>\n<h2 id=\"copy-json\">نسخ JSON: بيانات منظمة للمطورين</h2>\n<p>زر \"نسخ JSON\" يصدّر اللوحة كبيانات منظمة، مع كل لون مدرج مع قيمه HEX وRGB وHSL ونصيبه المئوي من الصورة.</p>\n<p>JSON هو الصيغة الصحيحة عندما تغذي اللوحة كودًا بدل ورقة أنماط: سير رموز تصميم أو مولد سمات أو ملف إعدادات قد يستهلك JSON مباشرة. ويشمل التصدير نفس البيانات التي تعرضها الشاشة، في شكل يستطيع سكربت معالجته: ذلك يجعل اللوحة قابلة لإعادة الاستخدام عبر مشاريع عدة دون أن يعيد أحد كتابتها.</p>\n<p>احفظ ملف JSON مع المشروع: عندما يحتاج نظام التصميم اللوحة مجددًا بعد أشهر، يكون الملف مصدر الحقيقة الوحيد، ولا يحتاج أحد إلى إعادة استخراجها من الصورة.</p>\n<h2 id=\"download-palette-png\">تنزيل لوحة PNG: بطاقة للمشاركة</h2>\n<p>زر \"تنزيل لوحة PNG\" يولّد بطاقة لوحة: الصورة الأصلية مع شريط العينات والألوان موضوعة تحتها: إنه ملخص بصري للاستخراج.</p>\n<p>البطاقة مفيدة لمشاركة لوحة مع عميل أو فريق: صورة للوحة تتواصل أسرع من قائمة أكواد HEX، خاصة مع أشخاص لا يقرأون كودًا. واستخدم البطاقة في لوحات مزاج ووثائق علامة وعروض تقديمية: تُظهر من أين جاءت الألوان، ما يبني ثقة في اللوحة، لأن العميل يستطيع رؤية الصورة المصدر.</p>\n<p>وتُولّد البطاقة محليًا في متصفحك، مثل كل شيء آخر في الأداة: لا بيانات صورة تغادر جهازك لإنتاجها.</p>\n<h2 id=\"extractor-vs-eyedropper\">المستخرج مقابل القطارة: سؤالان مختلفان</h2>\n<p>المستخرج والقطارة يجيبان سؤالين مختلفين: المستخرج يسأل أي ألوان تحدد الصورة كلها، بينما القطارة تسأل ما لون هذا البكسل.</p>\n<p>استخدم المستخرج عندما تريد أفكارًا: يُظهر اللوحة التي تحتويها صورة أصلًا، مرتبة حسب التغطية، وغالبًا يكشف ألوانًا ما كنت ستختارها بالنظر وحدها. واستخدم القطارة عندما تريد دقة: الأزرق الدقيق لشعار أو النغمة الدقيقة لزر أو الظل الدقيق لجدار تحتاج قراءة بكسل واحد.</p>\n<p>كثير من المصممين يستخدم الاثنين في سير واحد: يستخرجون لوحة للمخطط العام ثم يستخدمون المنتقي لأخذ لمسة دقيقة وضعها المستخرج منخفضًا جدًا ليشملها.</p>\n<h2 id=\"transparent-backgrounds\">خلفيات شفافة في PNG</h2>\n<p>ملفات PNG قد تحمل شفافية، ويتعامل المستخرج معها بتجاهل البكسلات الشفافة تمامًا عند بناء اللوحة: شعار على خلفية شفافة يساهم فقط بألوانه الخاصة.</p>\n<p>هذا مهم لأن منطقة شفافة ليس لها لون خاص: تضمينها سيضيف عينة زائفة، غالبًا بيضاء أو سوداء، لا تمثل شيئًا في التصميم. والبكسلات شبه الشفافة منطقة رمادية: بكسل نصف شفاف يمزج لونه مع ما خلفه، فيقرأ المستخرج النتيجة الممزوجة بدل اللون النقي.</p>\n<p>وللشعارات، يعمل المستخرج أفضل على خلفية صلبة: إذا بدت اللوحة سيئة، ضع الشعار أولًا على خلفية بيضاء أو بلون العلامة واستخرج من تلك النسخة.</p>\n<h2 id=\"tiny-accents\">لماذا قد لا تظهر لمسة نيون صغيرة</h2>\n<p>لمسة ساطعة صغيرة قد تختفي من لوحة، حتى عندما تكون أكثر جزء لا يُنسى في الصورة: السبب التغطية: المستخرج يرتب الألوان حسب كم من الصورة يغطيها.</p>\n<p>لافتة نيون تغطي 1 بالمئة من صورة هي جزء صغير، فالخوارزمية قد تطويها في لون مجاور بدل منحها عينة خاصة. ورفع عدد العينات يساعد: مع 12 لونًا، تحصل اللمسات الصغيرة على صناديقها الخاصة أكثر، لأن الخوارزمية تقسم الصورة إلى مجموعات أدق.</p>\n<p>وإذا لم تظهر اللمسة بعد، خذها بالقطارة: <a href=\"/ar/muntqi-alwan-as-sura/\">منتقي ألوان الصورة</a> يقرأ البكسل الدقيق، وتستطيع إضافة ذلك اللون إلى اللوحة المستخرجة يدويًا.</p>\n<h2 id=\"similar-shades\">لماذا يظهر ظلان متشابهان</h2>\n<p>لوحة 12 لونًا أحيانًا تُظهر عينتين تبدوان شبه متطابقتين: يحدث هذا عندما تكون منطقة كبيرة من الصورة تدرجًا ناعمًا، مثل سماء تمر من أزرق فاتح إلى أزرق أعمق.</p>\n<p>تقسم الخوارزمية ذلك التدرج إلى صندوقين، ويساهم كل صندوق بمتوسطه الخاص: المتوسطان قريبان، لكنهما فعلًا جزءان مختلفان من الصورة. وعندما ترى شبه مكررات، احتفظ بالذي يطابق تصميمك أفضل وتخلص من الآخر: لوحة بأزرق واحد أنظف من لوحة بأزرقين لا يستطيع أحد تمييزهما.</p>\n<p>وبديلًا، اخفض عدد العينات: مع 6 ألوان، يقع التدرج غالبًا في صندوق واحد، ويختفي المكرر من تلقاء نفسه.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: الاستخراج يحدث في متصفحك</h2>\n<p>استخراج اللوحة يشمل صورًا غالبًا حساسة: مفاهيم علامة لعملاء ولوحات مزاج غير منشورة وصور شخصية: رفعها إلى خادم خطر لا تحتاجه.</p>\n<p>المستخرج يقرأ الصورة محليًا: المتصفح يعيّن البكسلات وينفذ التكميم ويبني اللوحة دون إرسال بايت واحد إلى أي مكان. وهذا يعني أيضًا أن الأداة تعمل دون اتصال بمجرد تحميل الصفحة: تستطيع استخراج لوحات في طائرة أو غرفة اجتماعات أو مكتب آمن دون أي اتصال.</p>\n<p>وللفرق التي تتعامل مع عمل علامة سري، المعالجة المحلية هي الميزة الحاسمة: لا نسخة من الصورة توجد خارج جهازك في أي نقطة من السير.</p>\n<h2 id=\"weighting-a-design-by-percentage\">كيف توزن تصميمًا حسب النسبة المئوية</h2>\n<p>شارات النسبة المئوية أكثر من ملصقات؛ إنها وصفة للتصميم: لون بنسبة 45 بالمئة من الصورة يجب أن يشغل نحو 45 بالمئة من التصميم، لأن تلك النسبة هي ما تبدو طبيعية للعين.</p>\n<p>ابدأ تصميمًا بتعيين أكبر لون للخلفية: إنه اللون الذي اعتادت العين رؤيته في مناطق كبيرة، فصفحة مبنية عليه تشعر بالهدوء والألفة فورًا. وأعطِ ثاني أكبر لون لمناطق المحتوى الرئيسية: بطاقات ولوحات وأقسام: يدعم الخلفية دون منافستها، ومعًا يخلقان بنية الصفحة.</p>\n<p>واحتفظ بالألوان الأصغر للعناصر التي يجب أن تبرز: أزرار وروابط وتفاصيل مميزة: لون بنسبة 3 بالمئة مستخدم في 3 بالمئة من التصميم يجذب النظر بالضبط حيث تريده.</p>\n<p>وعندما لا تناسب النسب التصميم، اضبطها عمدًا: لوحة قد تحتاج أكثر من لون ثانوي مما في الصورة، وذلك جيد، ما دام التغيير قرارًا لا حادثًا.</p>\n<p>شريط الألوان النسبي هو أسرع طريقة لمراجعة الوزن: قارن الشريط بتصميمك جنبًا إلى جنب، وسيكون الفرق، إن وجد، واضحًا.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم مستخرج لوحة ألوان الصور</h2>\n<p>افتح <a href=\"/ar/istikraj-lauhat-alwan-min-as-sura/\">مستخرج لوحة ألوان الصور</a> وأسقط صورتك في منطقة الرفع، أو الصق لقطة مباشرة من الحافظة: تُقبل ملفات حتى 20 MB.</p>\n<p>حرّك المنزلق لاختيار بين 3 و12 عينة، بدءًا من القيمة الافتراضية 6: تُعاد بناء اللوحة فورًا، مع تحديث النسب وشريط الألوان النسبي.</p>\n<p>انسخ اللوحة كخصائص مخصصة لـCSS أو JSON، أو نزّل بطاقة اللوحة كـPNG لمشاركتها مع فريقك.</p>\n<p>للنسخة خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-istikraj-lauhat-alwan-min-as-sura/\">كيف تستخرج لوحة ألوان من صورة</a>، ولنصائح سير التصميم، راجع <a href=\"/ar/blog/lauhat-alwan-min-as-suwar-li-at-tasmim/\">لوحات ألوان من صور: نصائح سير تصميم</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"ما أفضل عدد ألوان للوحة موقع؟","answer":"ستة قيمة افتراضية جيدة، وهي الرقم الذي تبدأ به الأداة: تلتقط النغمات الرئيسية لمعظم الصور دون تقسيم نغمات متشابهة إلى مكررات. ولموقع أدنى، اخفض إلى 3، ولتصميم غني، ارفع إلى 8 أو 12."},{"question":"هل أستطيع استخراج لوحة من لقطة شاشة لموقع؟","answer":"نعم، الصق اللقطة مباشرة بـCtrl+V أو ارفع ملف اللقطة: يرتب المستخرج ألوان الواجهة، وهي طريقة سريعة لاستعادة لوحة موقع تعجبك. وتذكر أن ألوان الواجهة ملك مصمميها، فاستخدمها إلهامًا لا نسخًا."},{"question":"لماذا تتغير اللوحة عندما أرفع نفس الصورة مجددًا؟","answer":"لا يجب أن تتغير، ما دام الملف متطابقًا: إذا تغيرت اللوحة، فالملف غالبًا أُعيد حفظه أو ضغطه بين الرفعات، ما يغيّر قيم البكسل قليلًا. واستخرج دائمًا من الملف الأصلي للحصول على نتائج متسقة."},{"question":"كيف أستخدم لوحة مستخرجة في Figma أو Canva؟","answer":"انسخ أكواد HEX من العينات، أو استخدم تصدير \"نسخ CSS\" واقرأ القيم من هناك: الصق كل كود HEX في حقل اللون في Figma أو Canva لإعادة إنشاء اللوحة كأنماط لون. ويعطي تصدير JSON نفس البيانات في شكل منظم."},{"question":"هل يعمل المستخرج في صور بالأبيض والأسود؟","answer":"نعم، لكن اللوحة ستكون درجات رمادي، من شبه أسود إلى شبه أبيض، مع النسب التي تُظهر كم من الصورة يغطي كل نغمة: ذلك مفيد فعلًا، لأن التدرج الرمادي لصورة يكشف بنيتها النغمية."},{"question":"هل أستطيع استخراج لوحة من صورة على هاتفي؟","answer":"نعم، يعمل المستخرج في متصفحات الهاتف على iOS وAndroid: ارفع الصورة من معرضك وحرّك المنزلق لاختيار عدد العينات وانسخ CSS أو نزّل بطاقة اللوحة. وتعمل الميزة كاملة على شاشات صغيرة."}];
